import javax.swing.*;
import java.awt.*;
import java.sql.*;
import java.util.*;

public class TimetableHandler extends JPanel {
    private final boolean editable; private final DatabaseTimetable dao=new DatabaseTimetable(); private JTable table;
    public TimetableHandler(boolean editable){this.editable=editable;setLayout(new BorderLayout(8,8));setBorder(BorderFactory.createEmptyBorder(12,12,12,12));JPanel actions=new JPanel(new FlowLayout(FlowLayout.LEFT));JButton refresh=new JButton("Refresh");refresh.addActionListener(e->load());actions.add(refresh);if(editable){JButton add=new JButton("Add timetable slot");add.addActionListener(e->addSlot());JButton del=new JButton("Delete selected");del.addActionListener(e->delete());actions.add(add);actions.add(del);}add(actions,BorderLayout.NORTH);table=new JTable();add(new JScrollPane(table),BorderLayout.CENTER);load();}
    private void load(){try{JScrollPane old=(JScrollPane)getComponent(1);table=TableRender.table(new String[]{"ID","Day","Period","Code","Subject","Start","End","Room"},dao.all());remove(old);add(new JScrollPane(table),BorderLayout.CENTER);revalidate();repaint();}catch(Exception e){error(e);}}
    private void addSlot(){try{java.util.List<String[]> subjects=new ArrayList<>();try(Connection c=Database.getConnection();Statement s=c.createStatement();ResultSet r=s.executeQuery("SELECT id,code,name FROM subjects ORDER BY code")){while(r.next())subjects.add(new String[]{r.getString(1),r.getString(2)+" — "+r.getString(3)});}String[] days={"Monday","Tuesday","Wednesday","Thursday","Friday","Saturday"};JComboBox<String> day=new JComboBox<>(days),subject=new JComboBox<>();subject.addItem("Free period / no subject");for(String[] x:subjects)subject.addItem(x[1]);JTextField period=new JTextField("1"),start=new JTextField("09:00"),end=new JTextField("10:00"),room=new JTextField();Object[] f={"Day",day,"Period number",period,"Subject",subject,"Start time",start,"End time",end,"Room",room};if(JOptionPane.showConfirmDialog(this,f,"Add timetable slot",JOptionPane.OK_CANCEL_OPTION)!=JOptionPane.OK_OPTION)return;int p=Integer.parseInt(period.getText());if(p<1||p>12)throw new IllegalArgumentException("Period must be between 1 and 12.");Integer sid=subject.getSelectedIndex()==0?null:Integer.parseInt(subjects.get(subject.getSelectedIndex()-1)[0]);dao.add((String)day.getSelectedItem(),p,sid,start.getText().trim(),end.getText().trim(),room.getText().trim());load();}catch(Exception e){error(e);}}
    private void delete(){String id=TableRender.selectedId(table);if(id==null){JOptionPane.showMessageDialog(this,"Select a timetable slot first.");return;}if(JOptionPane.showConfirmDialog(this,"Delete selected slot?","Confirm",JOptionPane.YES_NO_OPTION)!=JOptionPane.YES_OPTION)return;try{dao.delete(Integer.parseInt(id));load();}catch(Exception e){error(e);}}
    private void error(Exception e){JOptionPane.showMessageDialog(this,e.getMessage(),"Timetable",JOptionPane.ERROR_MESSAGE);}
}
